-- v102 規則直し 便1 verify（読み取り）。KW_NEW|4（足した列の md5 が期待どおり）・OTHERS_SAME|4（ほかの列が変更前のまま）・MATCH|4（両方）・VERIFY_DONE が出ること。
-- 戻した後は、precheck の CAN_PROCEED|1 が再び出ることで確かめる。
SELECT 'KW_NEW|' || count(*) FROM public.line_conditions WHERE (code = 'CN0001' AND md5(exclude_kw) = '76f0408b4f328a26ea961871770c0213') OR (code = 'CN0002' AND md5(search_kw) = '76f0408b4f328a26ea961871770c0213') OR (code = 'CN0003' AND md5(exclude_kw) = '76f0408b4f328a26ea961871770c0213') OR (code = 'CN0004' AND md5(search_kw) = '8166ec8e5ff7aeac5006589fdbae6f04');
SELECT 'OTHERS_SAME|' || count(*) FROM public.line_conditions WHERE (code = 'CN0001' AND id = 12 AND canonical = 'Case' AND app_kubun = '箱系大' AND is_active = true AND priority = 4 AND created_at = '2026-09-19 16:35:26.371048+00:00'::timestamptz AND tenant_id IS NULL AND condition_def_id = 2 AND match_type = 'KEYWORD' AND effect = 'OUTPUT' AND unit_id = 9 AND md5(COALESCE(note,'')) = 'd41d8cd98f00b204e9800998ecf8427e' AND value_group = 'case' AND value_rank = 1 AND md5(COALESCE(search_kw,'')) = '454be54ff7f66973b0a737a746d0722f') OR (code = 'CN0002' AND id = 13 AND canonical = 'Damaged case' AND app_kubun = '箱系大' AND is_active = true AND priority = 2 AND created_at = '2026-09-19 16:35:26.371048+00:00'::timestamptz AND tenant_id IS NULL AND condition_def_id = 3 AND match_type = 'KEYWORD' AND effect = 'OUTPUT' AND unit_id = 9 AND md5(COALESCE(note,'')) = '70ff47440f8ce35b139f7fefbab52d6e' AND value_group = 'case' AND value_rank = 2 AND md5(COALESCE(exclude_kw,'')) = 'd41d8cd98f00b204e9800998ecf8427e') OR (code = 'CN0003' AND id = 14 AND canonical = 'Sealed box' AND app_kubun = '箱系' AND is_active = true AND priority = 4 AND created_at = '2026-09-19 16:35:26.371048+00:00'::timestamptz AND tenant_id IS NULL AND condition_def_id = 2 AND match_type = 'KEYWORD' AND effect = 'OUTPUT' AND unit_id = 10 AND md5(COALESCE(note,'')) = 'd41d8cd98f00b204e9800998ecf8427e' AND value_group = 'box' AND value_rank = 1 AND md5(COALESCE(search_kw,'')) = 'b153520fe5e8291bca582d70ab42877b') OR (code = 'CN0004' AND id = 16 AND canonical = 'Damaged sealed box' AND app_kubun = '箱系' AND is_active = true AND priority = 2 AND created_at = '2026-09-19 16:35:26.371048+00:00'::timestamptz AND tenant_id IS NULL AND condition_def_id = 3 AND match_type = 'KEYWORD' AND effect = 'OUTPUT' AND unit_id = 10 AND md5(COALESCE(note,'')) = 'd41d8cd98f00b204e9800998ecf8427e' AND value_group = 'box' AND value_rank = 2 AND md5(COALESCE(exclude_kw,'')) = 'd41d8cd98f00b204e9800998ecf8427e');
SELECT 'MATCH|' || count(*) FROM public.line_conditions
 WHERE ((code = 'CN0001' AND md5(exclude_kw) = '76f0408b4f328a26ea961871770c0213') OR (code = 'CN0002' AND md5(search_kw) = '76f0408b4f328a26ea961871770c0213') OR (code = 'CN0003' AND md5(exclude_kw) = '76f0408b4f328a26ea961871770c0213') OR (code = 'CN0004' AND md5(search_kw) = '8166ec8e5ff7aeac5006589fdbae6f04'))
   AND ((code = 'CN0001' AND id = 12 AND canonical = 'Case' AND app_kubun = '箱系大' AND is_active = true AND priority = 4 AND created_at = '2026-09-19 16:35:26.371048+00:00'::timestamptz AND tenant_id IS NULL AND condition_def_id = 2 AND match_type = 'KEYWORD' AND effect = 'OUTPUT' AND unit_id = 9 AND md5(COALESCE(note,'')) = 'd41d8cd98f00b204e9800998ecf8427e' AND value_group = 'case' AND value_rank = 1 AND md5(COALESCE(search_kw,'')) = '454be54ff7f66973b0a737a746d0722f') OR (code = 'CN0002' AND id = 13 AND canonical = 'Damaged case' AND app_kubun = '箱系大' AND is_active = true AND priority = 2 AND created_at = '2026-09-19 16:35:26.371048+00:00'::timestamptz AND tenant_id IS NULL AND condition_def_id = 3 AND match_type = 'KEYWORD' AND effect = 'OUTPUT' AND unit_id = 9 AND md5(COALESCE(note,'')) = '70ff47440f8ce35b139f7fefbab52d6e' AND value_group = 'case' AND value_rank = 2 AND md5(COALESCE(exclude_kw,'')) = 'd41d8cd98f00b204e9800998ecf8427e') OR (code = 'CN0003' AND id = 14 AND canonical = 'Sealed box' AND app_kubun = '箱系' AND is_active = true AND priority = 4 AND created_at = '2026-09-19 16:35:26.371048+00:00'::timestamptz AND tenant_id IS NULL AND condition_def_id = 2 AND match_type = 'KEYWORD' AND effect = 'OUTPUT' AND unit_id = 10 AND md5(COALESCE(note,'')) = 'd41d8cd98f00b204e9800998ecf8427e' AND value_group = 'box' AND value_rank = 1 AND md5(COALESCE(search_kw,'')) = 'b153520fe5e8291bca582d70ab42877b') OR (code = 'CN0004' AND id = 16 AND canonical = 'Damaged sealed box' AND app_kubun = '箱系' AND is_active = true AND priority = 2 AND created_at = '2026-09-19 16:35:26.371048+00:00'::timestamptz AND tenant_id IS NULL AND condition_def_id = 3 AND match_type = 'KEYWORD' AND effect = 'OUTPUT' AND unit_id = 10 AND md5(COALESCE(note,'')) = 'd41d8cd98f00b204e9800998ecf8427e' AND value_group = 'box' AND value_rank = 2 AND md5(COALESCE(exclude_kw,'')) = 'd41d8cd98f00b204e9800998ecf8427e'));
SELECT 'VERIFY_DONE';
